import { createContext } from "svelte";
import type { TooltipHandle } from "./handle.svelte.js";

const [getHandleContext, setHandleContext] = createContext<TooltipHandle>();

export function getTooltipHandleContext<Payload = unknown>(): TooltipHandle<Payload> {
  return getHandleContext() as unknown as TooltipHandle<Payload>;
}

export function setTooltipHandleContext<Payload>(handle: TooltipHandle<Payload>): void {
  setHandleContext(handle as unknown as TooltipHandle);
}

import { Tooltip as TooltipPrimitive } from "@shardsui/svelte";

export class TooltipHandle<Payload = unknown> extends TooltipPrimitive.Handle<Payload> {
  popupId = $state<string | undefined>(undefined);
}

export function createTooltipHandle<Payload = unknown>(): TooltipHandle<Payload> {
  return new TooltipHandle<Payload>();
}

import type { Snippet } from "svelte";
import type { HTMLButtonAttributes } from "svelte/elements";
import type { TooltipHandle } from "./handle.svelte.js";

export type TooltipTriggerState = {
  open: boolean;
};

export type TooltipRootState<Payload> = {
  payload: Payload | undefined;
};

export type TooltipRootProps<Payload = unknown> = {
  children?: Snippet<[TooltipRootState<Payload>]>;
  defaultOpen?: boolean;
  disableHoverablePopup?: boolean;
  disabled?: boolean;
  handle?: TooltipHandle<Payload>;
  onOpenChange?: (open: boolean) => void;
  onOpenChangeComplete?: (open: boolean) => void;
  open?: boolean | undefined;
  trackCursorAxis?: "none" | "x" | "y" | "both";
  triggerId?: string | null;
};

export type TooltipTriggerProps<Payload = unknown> = Omit<
  HTMLButtonAttributes,
  "children" | "id"
> & {
  as?: keyof HTMLElementTagNameMap;
  children?: Snippet<[TooltipTriggerState]>;
  closeDelay?: number;
  closeOnClick?: boolean;
  delay?: number;
  disabled?: boolean;
  handle?: TooltipHandle<Payload>;
  id?: string;
  payload?: Payload;
  ref?: HTMLElement | null;
};

import { Tooltip as TooltipPrimitive } from "@shardsui/svelte";

export {
  createTooltipHandle as TooltipCreateHandle,
  TooltipHandle as Handle,
} from "./handle.svelte.js";
export type {
  TooltipRootProps,
  TooltipRootState,
  TooltipTriggerProps,
  TooltipTriggerState,
} from "./tooltip.types.js";
export type { TooltipPopupProps, TooltipPortalProps } from "./tooltip-popup.svelte";
export {
  default as Content,
  default as Popup,
  default as TooltipContent,
  default as TooltipPopup,
} from "./tooltip-popup.svelte";
export type { TooltipProviderProps } from "./tooltip-provider.svelte";
export { default as Provider, default as TooltipProvider } from "./tooltip-provider.svelte";
export { default as Root, default as Tooltip, default as TooltipRoot } from "./tooltip-root.svelte";
export { default as TooltipTrigger, default as Trigger } from "./tooltip-trigger.svelte";
export { TooltipPrimitive };
